program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next((v for v, n in counts.most_common() if v != background), background)

    active = [any(v == foreground for v in row) for row in grid]
    groups = []
    start = None
    for r, yes in enumerate(active + [False]):
        if yes and start is None:
            start = r
        elif not yes and start is not None:
            groups.append((start, r))
            start = None
    if len(groups) < 2:
        return [row[:] for row in grid]

    # The two repeated strips are the active bands with the same row count.
    pairs = []
    for i in range(len(groups)):
        for j in range(i + 1, len(groups)):
            a, b = groups[i], groups[j]
            if a[1] - a[0] == b[1] - b[0]:
                pairs.append((a, b))
    if not pairs:
        return [row[:] for row in grid]
    a, b = max(pairs, key=lambda p: (p[0][1]-p[0][0], p[1][0]-p[0][0]))

    def rightmost(group):
        return max(c for r in range(group[0], group[1]) for c, v in enumerate(grid[r]) if v == foreground)

    # The shorter repeated strip is the one whose missing continuation is encoded.
    ra, rb = rightmost(a), rightmost(b)
    if ra <= rb:
        target, source = a, b
    else:
        target, source = b, a

    # Align the repeated prefixes; source column = target column + shift.
    best_shift, best_score = 0, -1
    target_right = rightmost(target)
    for shift in range(-5, 6):
        same = total = 0
        for offset in range(target[1] - target[0]):
            tr = target[0] + offset
            sr = source[0] + offset
            for c in range(target_right + 1):
                sc = c + shift
                if 0 <= sc < w:
                    same += grid[tr][c] == grid[sr][sc]
                    total += 1
        score = same / total if total else -1
        if score > best_score:
            best_score, best_shift = score, shift

    out = [row[:] for row in grid]
    for offset in range(target[1] - target[0]):
        tr = target[0] + offset
        sr = source[0] + offset
        row_end = max((c for c, v in enumerate(grid[tr]) if v == foreground), default=-1)
        for c in range(row_end + 1, w):
            sc = c + best_shift
            if 0 <= sc < w and grid[sr][sc] == foreground and grid[tr][c] == background:
                out[tr][c] = 1
    return out
'''
